package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Calendar;
import java.util.Locale;

public class AgentBRT_Lang_18_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // The pattern 'yyyy' should format the year as four digits
        FastDateFormat format = FastDateFormat.getInstance("yyyy", Locale.US);
        Calendar calendar = Calendar.getInstance();
        calendar.set(23, Calendar.JANUARY, 1); // Year 23 should be formatted as 0023
        String formattedDate = format.format(calendar);
        assertEquals("0023", formattedDate);
    }
}

