package org.apache.commons.lang3.time;

import org.junit.Test;
import static org.junit.Assert.*;

import java.text.ParseException;
import java.util.Locale;

public class AgentBRT_Lang_18_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // The pattern 'yy' should use TwoDigitYearField, but 'yyyy' should use selectNumberRule
        FastDateFormat format = FastDateFormat.getInstance("yyyy", Locale.US);
        try {
            // This should not throw an exception
            format.parse("2023");
        } catch (IllegalArgumentException e) {
            fail("Parsing failed for pattern 'yyyy' with input '2023': " + e.getMessage());
        }
    }
}

